/**
 * @fileoverview Tests for the `isConstant` AST utility.
 *
 * `isConstant(scope, node, inBooleanPosition)` reports whether the value
 * produced by an expression is constant. When `inBooleanPosition` is
 * `true` the expression is only ever used for its truthiness, so more
 * expressions qualify as constant.
 */

"use strict";

//------------------------------------------------------------------------------
// Requirements
//------------------------------------------------------------------------------

const espree = require("espree");
const {
	isConstant,
} = require("../../../../../lib/rules/utils/ast-utils");

//------------------------------------------------------------------------------
// Helpers
//------------------------------------------------------------------------------

const PARSE_OPTIONS = { ecmaVersion: "latest", sourceType: "script" };

/**
 * Parses a single expression and returns its root AST node.
 * @param {string} code Source text of the expression.
 * @returns {ASTNode} The expression node.
 */
function parseExpression(code) {
	return espree.parse(`(${code});`, PARSE_OPTIONS).body[0].expression;
}

/**
 * Collects the node itself and all of its descendants.
 * @param {ASTNode} node Root node.
 * @param {ASTNode[]} [nodes] Accumulator.
 * @returns {ASTNode[]} All visited nodes.
 */
function collectNodes(node, nodes = []) {
	if (!node || typeof node.type !== "string") {
		return nodes;
	}
	nodes.push(node);
	for (const key of Object.keys(node)) {
		if (key === "parent") {
			continue;
		}
		const value = node[key];

		if (Array.isArray(value)) {
			value.forEach(child => collectNodes(child, nodes));
		} else if (value && typeof value.type === "string") {
			collectNodes(value, nodes);
		}
	}
	return nodes;
}

/**
 * Returns every `Identifier` node contained in an expression.
 * @param {ASTNode} node Root node.
 * @returns {ASTNode[]} Identifier nodes.
 */
function identifiersOf(node) {
	return collectNodes(node).filter(child => child.type === "Identifier");
}

/**
 * Finds the identifier with the given name inside an expression.
 * @param {ASTNode} node Root node.
 * @param {string} name Identifier name.
 * @returns {ASTNode} The matching identifier node.
 */
function identifierNamed(node, name) {
	const identifier = identifiersOf(node).find(
		child => child.name === name,
	);

	if (!identifier) {
		throw new Error(`No identifier named "${name}" in expression.`);
	}
	return identifier;
}

/**
 * Builds a minimal scope stub exposing the `references` array that
 * `isConstant` consults through `isReferenceToGlobalVariable`.
 * @param {Object} [options] Options.
 * @param {ASTNode[]} [options.globals] Identifiers resolving to global variables.
 * @param {ASTNode[]} [options.locals] Identifiers resolving to local variables.
 * @returns {Object} A scope-like object.
 */
function createScope({ globals = [], locals = [] } = {}) {
	return {
		references: [
			...globals.map(identifier => ({
				identifier,
				resolved: { scope: { type: "global" }, defs: [] },
			})),
			...locals.map(identifier => ({
				identifier,
				resolved: {
					scope: { type: "function" },
					defs: [{ type: "Parameter" }],
				},
			})),
		],
	};
}

/**
 * Convenience wrapper: evaluates `isConstant` for a parsed expression.
 * @param {string} code Source text of the expression.
 * @param {boolean} inBooleanPosition Whether the expression is used as a condition.
 * @param {Object} [scopeOptions] Options forwarded to `createScope`.
 * @returns {boolean} The result of `isConstant`.
 */
function check(code, inBooleanPosition, scopeOptions) {
	const node = parseExpression(code);

	return isConstant(createScope(scopeOptions), node, inBooleanPosition);
}

//------------------------------------------------------------------------------
// Tests
//------------------------------------------------------------------------------

describe("isConstant", () => {
	describe("empty nodes", () => {
		it("returns true for a null node (sparse array holes)", () => {
			const scope = createScope();

			expect(isConstant(scope, null, false)).toBe(true);
			expect(isConstant(scope, null, true)).toBe(true);
		});

		it("returns true for an undefined node", () => {
			const scope = createScope();

			expect(isConstant(scope, void 0, false)).toBe(true);
		});
	});

	describe("node types that are always constant", () => {
		it.each([
			["number literal", "42"],
			["string literal", "'hello'"],
			["empty string literal", "''"],
			["boolean literal", "true"],
			["null literal", "null"],
			["regular expression literal", "/a/g"],
			["bigint literal", "10n"],
			["arrow function", "() => value"],
			["function expression", "function () { return value; }"],
			["object expression with computed values", "({ a: value })"],
			["object expression with no properties", "({})"],
		])("returns true for a %s", (description, code) => {
			expect(check(code, false)).toBe(true);
			expect(check(code, true)).toBe(true);
		});

		it("returns true for a class expression", () => {
			const code = "(class { static valueOf() { return value; } })";

			expect(check(code, false)).toBe(true);
			expect(check(code, true)).toBe(true);
		});
	});

	describe("TemplateLiteral", () => {
		it("returns true when used in a boolean position and a quasi is non-empty", () => {
			expect(check("`a${value}`", true)).toBe(true);
		});

		it("returns true when used in a boolean position and the template starts with text", () => {
			expect(check("`prefix`", true)).toBe(true);
		});

		it("returns true when every expression is constant and no quasi has text", () => {
			expect(check("`${1}${2}`", false)).toBe(true);
			expect(check("`${1}${2}`", true)).toBe(true);
		});

		it("returns false when an expression is not constant, even if a quasi has text", () => {
			expect(check("`a${value}`", false)).toBe(false);
		});

		it("returns false when no quasi has text and an expression is not constant", () => {
			expect(check("`${value}`", true)).toBe(false);
			expect(check("`${value}`", false)).toBe(false);
		});

		it("returns false when a nested non-constant expression is embedded", () => {
			expect(check("`${1}${value + 1}`", false)).toBe(false);
		});
	});

	describe("ArrayExpression", () => {
		it("returns true in a boolean position regardless of the elements", () => {
			expect(check("[value]", true)).toBe(true);
			expect(check("[[value]]", true)).toBe(true);
		});

		it("returns true when every element is constant in a non-boolean position", () => {
			expect(check("[1, 'two', [3]]", false)).toBe(true);
			expect(check("[]", false)).toBe(true);
		});

		it("returns false when an element is not constant in a non-boolean position", () => {
			expect(check("[value]", false)).toBe(false);
			expect(check("[1, [value]]", false)).toBe(false);
		});

		it("treats sparse array holes as constant", () => {
			expect(check("[,]", false)).toBe(true);
			expect(check("[, ,]", true)).toBe(true);
		});
	});

	describe("UnaryExpression", () => {
		it("returns true for `void` in both positions", () => {
			expect(check("void value", false)).toBe(true);
			expect(check("void value", true)).toBe(true);
		});

		it("returns true for `typeof` only in a boolean position", () => {
			expect(check("typeof value", true)).toBe(true);
			expect(check("typeof value", false)).toBe(false);
		});

		it("returns true for `typeof` of a constant in a non-boolean position", () => {
			expect(check("typeof 1", false)).toBe(true);
		});

		it("checks the argument of `!` in a boolean position", () => {
			expect(check("!value", true)).toBe(false);
			expect(check("!1", true)).toBe(true);
			expect(check("!void value", true)).toBe(true);
			expect(check("![value]", true)).toBe(true);
		});

		it("checks the argument of other operators in a non-boolean position", () => {
			expect(check("-value", true)).toBe(false);
			expect(check("-1", true)).toBe(true);
			expect(check("~value", false)).toBe(false);
			expect(check("delete value", false)).toBe(false);
		});
	});

	describe("BinaryExpression", () => {
		it("returns true when both operands are constant", () => {
			expect(check("1 + 2", false)).toBe(true);
			expect(check("1 === 1", true)).toBe(true);
		});

		it("returns false when an operand is not constant", () => {
			expect(check("value + 1", false)).toBe(false);
			expect(check("1 + value", false)).toBe(false);
		});

		it("returns false for the `in` operator even when both operands are constant", () => {
			expect(check("1 in 2", false)).toBe(false);
			expect(check("'a' in { a: 1 }", true)).toBe(false);
		});

		it("does not treat a binary expression as boolean-position dependent", () => {
			expect(check("value < 10", true)).toBe(false);
		});
	});

	describe("LogicalExpression", () => {
		it("returns true when both operands are constant", () => {
			expect(check("1 && 2", false)).toBe(true);
			expect(check("1 || 2", true)).toBe(true);
		});

		it("returns false when both operands are not constant", () => {
			expect(check("left && right", true)).toBe(false);
			expect(check("left || right", false)).toBe(false);
		});

		it("returns true when the left operand short-circuits the whole expression", () => {
			expect(check("true || right", false)).toBe(true);
			expect(check("false && right", true)).toBe(true);
		});

		it("returns false when the left operand is constant but not an identity element", () => {
			expect(check("false || right", false)).toBe(false);
			expect(check("true && right", true)).toBe(false);
		});

		it("returns true when the right operand short-circuits in a boolean position", () => {
			expect(check("left && false", true)).toBe(true);
			expect(check("left || true", true)).toBe(true);
			expect(check("left && 0", true)).toBe(true);
			expect(check("left || 'x'", true)).toBe(true);
		});

		it("does not consider right-hand short-circuiting outside a boolean position", () => {
			expect(check("left && false", false)).toBe(false);
			expect(check("left || true", false)).toBe(false);
		});

		it("returns false when the right operand is not an identity element", () => {
			expect(check("left && 1", true)).toBe(false);
			expect(check("left || ''", true)).toBe(false);
			expect(check("left && ({})", true)).toBe(false);
		});

		it("propagates short-circuiting through nested logical expressions", () => {
			expect(check("left && (false && right)", true)).toBe(true);
			expect(check("left && (false && right)", false)).toBe(false);
			expect(check("(true || left) && right", true)).toBe(false);
		});
	});

	describe("NewExpression", () => {
		it("returns true only in a boolean position", () => {
			expect(check("new Foo()", true)).toBe(true);
			expect(check("new Foo()", false)).toBe(false);
		});
	});

	describe("AssignmentExpression", () => {
		it("returns true for `=` when the right side is constant", () => {
			expect(check("value = 1", false)).toBe(true);
			expect(check("value = [1]", false)).toBe(true);
			expect(check("value = [other]", true)).toBe(true);
		});

		it("returns false for `=` when the right side is not constant", () => {
			expect(check("value = other", false)).toBe(false);
			expect(check("value = [other]", false)).toBe(false);
		});

		it("returns false for compound assignments that are not logical", () => {
			expect(check("value += 1", false)).toBe(false);
			expect(check("value += 1", true)).toBe(false);
		});

		it("returns true for logical assignments whose right side is an identity element in a boolean position", () => {
			expect(check("value ||= true", true)).toBe(true);
			expect(check("value &&= 0", true)).toBe(true);
		});

		it("returns false for logical assignments that are not identity elements", () => {
			expect(check("value ||= false", true)).toBe(false);
			expect(check("value &&= 1", true)).toBe(false);
		});

		it("returns false for logical assignments outside a boolean position", () => {
			expect(check("value ||= true", false)).toBe(false);
			expect(check("value &&= 0", false)).toBe(false);
		});

		it("returns false for nullish logical assignments", () => {
			expect(check("value ??= 1", true)).toBe(false);
		});
	});

	describe("SequenceExpression", () => {
		it("uses the last expression of the sequence", () => {
			expect(check("(other, 1)", false)).toBe(true);
			expect(check("(1, other)", false)).toBe(false);
		});

		it("passes the boolean position down to the last expression", () => {
			expect(check("(other, [item])", true)).toBe(true);
			expect(check("(other, [item])", false)).toBe(false);
		});
